content.text:
The fault is a network loss fault on the ts-contacts-service → ts-preserve-service connection. Its effect reaches the user through ts-preserve-service to ts-ui-dashboard.

```json
{
  "root_causes": [
    {
      "service": "ts-contacts-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT date_trunc('minute', time) m, attr_source, attr_destination, SUM(value) drops FROM abnormal_metrics_sum WHERE metric = 'hubble_drop_total' AND attr_destination LIKE '%ts-preserve-service%' GROUP BY ALL ORDER BY 1,2",
          "claim": "Drops on the contacts→preserve connection appear in the abnormal window (up to 6/min), with none in the normal baseline."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' AS per, s.service_name callee, s.span_name, COUNT(*) n, ROUND(quantile_cont(c.duration,0.5)/1e6,1) cli_p50, ROUND(quantile_cont(c.duration,0.95)/1e6,1) cli_p95, ROUND(quantile_cont(s.duration,0.5)/1e6,1) srv_p50, ROUND(quantile_cont(s.duration,0.95)/1e6,1) srv_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-preserve-service' AND c.attr_span_kind='Client' AND s.service_name='ts-contacts-service' GROUP BY ALL UNION ALL SELECT 'norm' AS per, s.service_name, s.span_name, COUNT(*), ROUND(quantile_cont(c.duration,0.5)/1e6,1), ROUND(quantile_cont(c.duration,0.95)/1e6,1), ROUND(quantile_cont(s.duration,0.5)/1e6,1), ROUND(quantile_cont(s.duration,0.95)/1e6,1) FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-preserve-service' AND c.attr_span_kind='Client' AND s.service_name='ts-contacts-service' GROUP BY ALL",
          "claim": "Preserve's client calls to contacts take p50 1.67 s (p95 53 s) while contacts' server spans stay at about 7 ms."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-contacts-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' AS per, s.service_name callee, s.span_name, COUNT(*) n, ROUND(quantile_cont(c.duration,0.5)/1e6,1) cli_p50, ROUND(quantile_cont(c.duration,0.95)/1e6,1) cli_p95, ROUND(quantile_cont(s.duration,0.5)/1e6,1) srv_p50, ROUND(quantile_cont(s.duration,0.95)/1e6,1) srv_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-preserve-service' AND c.attr_span_kind='Client' AND s.service_name='ts-contacts-service' GROUP BY ALL",
          "claim": "Slow contacts calls from preserve: client-side p95 53 s while the contacts server span p95 is 9.7 ms."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, ROUND(quantile_cont(duration,0.5)/1e6,1) p50, ROUND(quantile_cont(duration,0.95)/1e6,1) p95, ROUND(AVG(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END),3) err FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%preserve%' GROUP BY ALL",
          "claim": "ui-dashboard's POST preserve requests reach p50 4.5 s and p95 20 s in the abnormal window, versus about 1 s p95 normally."
        }
      ]
    }
  ]
}
```

